CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Ejercicios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(150) NOT NULL,
    "GrupoMuscular" character varying(100) NOT NULL,
    "EsUnilateral" boolean NOT NULL DEFAULT FALSE,
    CONSTRAINT "PK_Ejercicios" PRIMARY KEY ("Id")
);

CREATE TABLE "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" character varying(256) NOT NULL,
    "PasswordHash" character varying(500) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "TiempoDescansoDefectoSegundos" integer NOT NULL DEFAULT 90,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id")
);

CREATE TABLE "Rutinas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "DiaSugerido" character varying(50),
    "Activa" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Rutinas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Rutinas_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE
);

CREATE TABLE "RutinaEjercicios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RutinaId" integer NOT NULL,
    "EjercicioId" integer NOT NULL,
    "Orden" integer NOT NULL,
    "SeriesObjetivo" integer NOT NULL,
    "DescansoSegundos" integer,
    CONSTRAINT "PK_RutinaEjercicios" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RutinaEjercicios_Ejercicios_EjercicioId" FOREIGN KEY ("EjercicioId") REFERENCES "Ejercicios" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_RutinaEjercicios_Rutinas_RutinaId" FOREIGN KEY ("RutinaId") REFERENCES "Rutinas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SesionesEntrenamiento" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" integer NOT NULL,
    "RutinaId" integer NOT NULL,
    "FechaHoraInicio" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "FechaHoraFin" timestamp with time zone,
    "Notas" character varying(1000),
    CONSTRAINT "PK_SesionesEntrenamiento" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SesionesEntrenamiento_Rutinas_RutinaId" FOREIGN KEY ("RutinaId") REFERENCES "Rutinas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SesionesEntrenamiento_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SeriesRegistro" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SesionId" integer NOT NULL,
    "EjercicioId" integer NOT NULL,
    "NumeroSerie" integer NOT NULL,
    "PesoKg" numeric(5,2) NOT NULL,
    "Repeticiones" integer NOT NULL,
    "Lado" character(1),
    "RPE" numeric(3,1),
    CONSTRAINT "PK_SeriesRegistro" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SeriesRegistro_Ejercicios_EjercicioId" FOREIGN KEY ("EjercicioId") REFERENCES "Ejercicios" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SeriesRegistro_SesionesEntrenamiento_SesionId" FOREIGN KEY ("SesionId") REFERENCES "SesionesEntrenamiento" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_Ejercicios_GrupoMuscular" ON "Ejercicios" ("GrupoMuscular");

CREATE INDEX "IX_RutinaEjercicios_EjercicioId" ON "RutinaEjercicios" ("EjercicioId");

CREATE INDEX "IX_RutinaEjercicios_RutinaId_Orden" ON "RutinaEjercicios" ("RutinaId", "Orden");

CREATE INDEX "IX_Rutinas_UsuarioId_Activa" ON "Rutinas" ("UsuarioId", "Activa");

CREATE INDEX "IX_SeriesRegistro_EjercicioId" ON "SeriesRegistro" ("EjercicioId");

CREATE INDEX "IX_SeriesRegistro_SesionId_EjercicioId_NumeroSerie" ON "SeriesRegistro" ("SesionId", "EjercicioId", "NumeroSerie");

CREATE INDEX "IX_SesionesEntrenamiento_RutinaId" ON "SesionesEntrenamiento" ("RutinaId");

CREATE INDEX "IX_SesionesEntrenamiento_UsuarioId_FechaHoraInicio" ON "SesionesEntrenamiento" ("UsuarioId", "FechaHoraInicio");

CREATE UNIQUE INDEX "IX_Usuarios_Email" ON "Usuarios" ("Email");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261008221201_InitialCreate_GymApp', '10.0.12');

COMMIT;

