ALTER TABLE "Usuarios" ADD "Rol" character varying(50) NOT NULL DEFAULT 'User';

ALTER TABLE "Ejercicios" ADD "UsuarioId" integer;

CREATE INDEX "IX_Ejercicios_UsuarioId" ON "Ejercicios" ("UsuarioId");

ALTER TABLE "Ejercicios" ADD CONSTRAINT "FK_Ejercicios_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE;

